public class OrderProcessor {

    // CORRECT: Avoids control flow exceptions, does not swallow, catches specific types
    public OrderStatus processOrder(String orderId) {
        if (orderId == null || orderId.isBlank()) {
            return OrderStatus.INVALID; // Pure conditional control flow
        }

        try {
            Order order = externalInventoryClient.fetchOrder(orderId);
            if (order == null) {
                return OrderStatus.NOT_FOUND;
            }
            return executeFulfillment(order);
        } catch (DataAccessException | NetworkTimeoutException e) {
            // CORRECT: Preserves context by wrapping in a domain exception or logging with full stack trace
            log.error("Failed to process order ID: {}", orderId, e);
            throw new OrderProcessingException("Transient infrastructure failure", e);
        }
        // INCORRECT TO CATCH: catch (Throwable t) { /* Never do this */ }
    }
}
